from pathlib import Path

p=Path('app/src/v7/java/com/mg/battleship/GameActivity.java')
s=p.read_text(encoding='utf-8')

def rep(old,new,label):
    global s
    if old not in s:
        raise SystemExit('missing patch target: '+label)
    s=s.replace(old,new,1)

rep('private TextView status,rankText;\n    private BoardView board;\n    private Button rotate,randomize,ready;',
    'private TextView status,rankText,battleHud;\n    private BoardView board;\n    private Button rotate,randomize,ready;\n    private LinearLayout setupControls;','fields-ui')
rep('private int aiLevel=2,careerStage=0;',
    'private int aiLevel=2,careerStage=0;\n    private int matchShots=0,matchHits=0,enemySunkCount=0;','fields-stats')
rep('TextView footer=label("v7 • Sinematik savaş • Kariyer • Rütbe • Gelişmiş AI",11,Color.rgb(120,145,155));',
    'TextView footer=label("v8 • Kesintisiz savaş • Batış efektleri • Canlı HUD • Gelişmiş AI",11,Color.rgb(120,145,155));','footer')
